    public record Relation(Availability availability,BigInteger faithId,Optional<Boolean> faithListsSite,Optional<Boolean> eminent){public Relation{Objects.requireNonNull(availability);Objects.requireNonNull(faithId);Objects.requireNonNull(faithListsSite);Objects.requireNonNull(eminent);}}
