    public static State body(JsonNode original,BigInteger nativeRevision,BigInteger date,BigInteger actor,Optional<BigInteger> requested){
        ObjectNode n=object(original).deepCopy();equal(n,"schema","ck3_12004_player_holy_site_v1");need(build(n)==Build.CROZIER4,"HolySite state requires exact .4");Availability available=strictAvailability(n);equal(n,"played_character_id",actor);number(n,"played_character_id",I32_MIN,I32_MAX);need(!actor.equals(BigInteger.valueOf(-1)),"native signed snapshot actor sentinel is unavailable");equal(n,"date_raw",date);number(n,"date_raw",I32_MIN,I32_MAX);BigInteger epoch=number(n,"capture_epoch",BigInteger.ONE,U64);
        Optional<BigInteger> request=Optional.ofNullable(nullableId(n,"requested_holy_site_id"));need(request.equals(requested),"HolySite state crossed its explicit full reference");Optional<BigInteger> rite=Optional.ofNullable(nullableId(n,"player_rite_id")),faith=Optional.ofNullable(nullableId(n,"player_faith_id"));Frame frame=new Frame(Build.CROZIER4,epoch,nativeRevision,date,actor,available);
        if(!available.available()){for(String field:List.of("current_faith_holy_site_ids","current_faith_sites","window_model","selected_holy_site","loaded_registry_roster"))n.putNull(field);return new State(frame,rite,faith,requested,Optional.empty(),Optional.empty(),Optional.empty(),Optional.empty(),Optional.empty(),ReligionCodec.raw(n));}
        List<BigInteger> ids=orderedIds(field(n,"current_faith_holy_site_ids"));JsonNode rawSites=field(n,"current_faith_sites");need(rawSites.isArray()&&rawSites.size()==ids.size(),"current Faith HolySite rows omitted source identities");var sites=new ArrayList<Site>();for(JsonNode site:rawSites)sites.add(site(site));need(sites.stream().map(Site::id).toList().equals(ids),"current Faith HolySite order/identities changed");
        ObjectNode w=object(field(n,"window_model"));Availability wa=strictAvailability(w);Optional<BigInteger> wid=Optional.ofNullable(nullableId(w,"holy_site_id")),item=Optional.ofNullable(nullableId(w,"holy_site_item_raw"));Optional<Boolean> present=optionalBool(w,"present"),root=optionalBool(w,"root_present");need(wa.available()?present.isPresent()&&root.isPresent():present.isEmpty()&&root.isEmpty(),"HolySite model availability differs");no(w,"rendered_visibility_observed");Window window=new Window(wa,wid,item,present,root);
        Optional<BigInteger> selectedId=requested.isPresent()?requested:wid;Optional<Site> selected=field(n,"selected_holy_site").isNull()?Optional.empty():Optional.of(site(field(n,"selected_holy_site")));need(selected.isPresent()==selectedId.isPresent()&&(selected.isEmpty()||selected.orElseThrow().id().equals(selectedId.orElseThrow())),"HolySite selected source identity differs");equal(n,"selection_source",requested.isPresent()?"explicit_full_reference":"registered_window_model");
        JsonNode rows=field(n,"loaded_registry_roster");need(rows.isArray()&&rows.size()<=8192,"bounded loaded registry roster required");bool(n,"loaded_registry_roster_available");no(n,"registry_roster_is_native_adoption_candidates");int slots=number(n,"loaded_registry_slot_count",BigInteger.ZERO,BigInteger.valueOf(8192)).intValueExact(),unreadable=number(n,"loaded_registry_unreadable_slots",BigInteger.ZERO,BigInteger.valueOf(8192)).intValueExact();need(rows.size()+unreadable<=slots,"registry rows exceed actual slots");var roster=new ArrayList<Roster>();for(JsonNode row:rows){String key=text(row,"type_key");need(!key.isEmpty(),"loaded registry type missing");roster.add(new Roster(id(row,"holy_site_id"),Optional.ofNullable(nullableId(row,"barony_title_id")),key));}
        for(String flag:List.of("active_state_observed","relic_recognition_observed","beneficiaries_observed","adoption_legality_observed"))no(n,flag);yes(n,"read_only");return new State(frame,rite,faith,requested,Optional.of(ids),Optional.of(sites),Optional.of(window),selected,Optional.of(roster),ReligionCodec.raw(n));
    }
    private static Site site(JsonNode value){
        ObjectNode n=object(value);Availability available=strictAvailability(n);BigInteger id=id(n,"holy_site_id");Optional<String> type=Optional.ofNullable(nullableText(n,"type_key"));type.ifPresent(v->need(!v.isEmpty()&&v.codePointCount(0,v.length())<=1024,"native HolySite type key malformed"));Optional<BigInteger> barony=Optional.ofNullable(nullableId(n,"barony_title_id"));JsonNode rows=field(n,"associated_faiths");need(rows.isArray()&&rows.size()<=8192,"bounded associated Faith rows required");var relations=new ArrayList<Relation>();for(JsonNode row:rows){Availability a=strictAvailability(row);Optional<Boolean> lists=optionalBool(row,"faith_lists_site"),eminent=optionalBool(row,"eminent");need(a.available()?lists.isPresent()&&eminent.isPresent():lists.isEmpty()&&eminent.isEmpty(),"Faith membership availability differs");relations.add(new Relation(a,id(row,"faith_id"),lists,eminent));}
        ObjectNode i=object(field(n,"inventory"));Availability ia=strictAvailability(i);equal(i,"identity_kind","embedded_holy_site_inventory");equal(i,"owner_kind","holy_site");equal(i,"owner_holy_site_id",id);no(i,"artifact_objects_resolved");Optional<List<BigInteger>> artifacts=ia.available()?Optional.of(orderedIds(field(i,"artifact_ids"))):Optional.empty();if(!ia.available())nil(i,"artifact_ids");Inventory inventory=new Inventory(ia,Optional.ofNullable(nullableId(i,"native_holy_site_owner_id")),Optional.ofNullable(nullableId(i,"native_character_owner_id")),artifacts);need(!available.available()||type.isPresent()&&ia.available(),"available HolySite lacks actual type/inventory");return new Site(available,id,type,barony,relations,inventory);
    }
    private static List<BigInteger> orderedIds(JsonNode values){need(values.isArray()&&values.size()<=8192,"bounded complete native identity array required");var result=new ArrayList<BigInteger>();for(JsonNode value:values)result.add(scalar(value,BigInteger.ZERO,U32.subtract(BigInteger.ONE)));return List.copyOf(result);}
    private static Optional<Boolean> optionalBool(JsonNode row,String field){return field(row,field).isNull()?Optional.empty():Optional.of(bool(row,field));}
    private static Availability strictAvailability(JsonNode row){boolean value=bool(row,"available");JsonNode reason=field(row,"unavailable_reason");need(value?reason.isNull():reason.isTextual()&&!reason.textValue().isEmpty(),"original HolySite availability lost null/diagnostic distinction");return new Availability(value,value?null:reason.textValue());}
